export function modelViewTools(){const button=(action,label,toggle=false)=>`<button type="button" data-composite-view="${action}" aria-label="${label}" title="${label}" ${toggle?`aria-pressed="${action==='rotate'||action==='axes'}"`:''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[action]}"/></svg></button>`;return `<div class="model-view-toolbar" role="toolbar" aria-label="模型视图快捷工具">${button('in','放大模型')}${button('out','缩小模型')}${button('reset','适应全部几何体')}<i></i>${button('select','选择材料',true)}${button('rotate','旋转模型',true)}${button('pan','平移模型',true)}<i></i>${button('wireframe','线框显示',true)}${button('hide','隐藏选中材料')}${button('show','显示全部材料')}${button('axes','显示坐标轴',true)}<i></i>${button('capture','导出模型截图')}<output data-model-view-status>旋转 · 100%</output></div>`;}
